async function fetchJsonLoose(url: string, params: Record<string,string|number|boolean>): Promise<any> {
  const u = new URL(url);
  for (const [k,v] of Object.entries(params)) u.searchParams.set(k, String(v));
  const res = await fetch(u, { signal: AbortSignal.timeout(30000), headers:{ 'user-agent':'IrelandPublicBrain/0.1 (+https://ireland-public-context-graph.pages.dev)' } });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}
